<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Request;use App\Core\Response;final class AuthController extends \App\Controllers\AuthController{protected string $layout='layouts/admin_auth';protected string $loginView='admin/login';protected bool $adminOnly=true;public function loginForm(Request $j):Response{if(\App\Core\Auth::isAdmin()){return $this->redirect('/admin');}return parent::loginForm($j);}}